with cleaned as (select *, date_format(last_restock, 'yyyy-MM') last_restock_label from inventory where product_id in (4, 6)) select id, store_id, product_id, quantity, last_restock, last_restock_label, count(quantity) over w_ordered last7_count_quantity, min(quantity) over w_ordered last7_min_quantity, avg(quantity) over w_ordered last7_avg_quantity, sum(quantity) over w_ordered last7_sum_quantity, lag(quantity, 1) over (partition by store_id order by quantity asc, id asc) prev_quantity from cleaned where product_id in (5, 7, 9, 10) window w_ordered as (partition by store_id order by last_restock asc, id asc rows between 6 preceding and current row)
